/**
 * @file src/stores/achievementSnapshotDiff.ts
 * Pure comparison for ACHIEVEMENTS_CHANGED publish deduplication.
 */

import type { AchievementsSnapshot } from '../bus/snapshots.js';

function categoriesEqual(
  a: AchievementsSnapshot['categories'],
  b: AchievementsSnapshot['categories'],
): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const ac = a[i];
    const bc = b[i];
    if (ac === undefined || bc === undefined) return false;
    if (ac.categoryId !== bc.categoryId || ac.title !== bc.title) return false;
    if (ac.cards.length !== bc.cards.length) return false;
    for (let j = 0; j < ac.cards.length; j++) {
      const ak = ac.cards[j];
      const bk = bc.cards[j];
      if (ak === undefined || bk === undefined) return false;
      if (
        ak.achievementKey !== bk.achievementKey
        || ak.cardHtml !== bk.cardHtml
        || ak.cardClass !== bk.cardClass
      ) {
        return false;
      }
    }
  }
  return true;
}

export function achievementsSnapshotWouldChange(
  prev: AchievementsSnapshot,
  next: AchievementsSnapshot,
): boolean {
  return (
    prev.language !== next.language
    || prev.emptyHtml !== next.emptyHtml
    || prev.achievementsCount !== next.achievementsCount
    || prev.achievementsTotal !== next.achievementsTotal
    || !categoriesEqual(prev.categories, next.categories)
  );
}
