/**
 * @file src/lib/achievementSnapshot.ts
 * Read-only snapshot for QuestPanel achievements (succès) tab.
 */

import type { GameRuntime } from '../types/game.js';
import type {
  AchievementCardSnapshot,
  AchievementCategorySnapshot,
  AchievementsSnapshot,
} from '../bus/snapshots.js';
import { publish } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import { achievementsSnapshotWouldChange } from '../stores/achievementSnapshotDiff.js';
import { ACHIEVEMENTS, ALL_ITEMS, formatNumber, formatTimeString } from '@snapshot/achievements';

const CATEGORY_ORDER = [
  'progression',
  'combat',
  'capture',
  'collection',
  'economy',
  'breeding',
  'items',
  'quests',
  'exploration',
  'tower_endgame',
  'team_rocket',
  'other',
] as const;

const EGG_SPRITE_BY_RARITY: Record<string, string> = {
  common: 'img/common-egg.png',
  rare: 'img/rare-egg.png',
  epic: 'img/epic-egg.png',
  legendary: 'img/legendary-egg.png',
};

interface VisibleAchievement {
  key: string;
  trackingKey: string;
  target: number;
  rewards?: {
    pokedollars?: number;
    questTokens?: number;
    tokens?: number;
    talentRerolls?: number;
    talentChoices?: number;
    items?: Record<string, number>;
    eggs?: Record<string, number>;
  };
}

function buildRewardsHTML(game: GameRuntime, ach: VisibleAchievement): string {
  if (!ach.rewards) return '';

  const rewardParts: string[] = [];
  const r = ach.rewards;

  if (r.pokedollars) {
    rewardParts.push(
      `<span class="quest-reward-item"><img src="img/pokedollars.png" class="quest-reward-inline-img" alt="Pokedollars"> ${formatNumber(r.pokedollars)}</span>`,
    );
  }
  const achTokenReward = Number(r.questTokens || r.tokens || 0);
  if (achTokenReward > 0) {
    rewardParts.push(
      `<span class="quest-reward-item"><img src="https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/magma-emblem.png" class="quest-token-inline" alt=""> ${achTokenReward}</span>`,
    );
  }
  if (r.talentRerolls) {
    rewardParts.push(
      `<span class="quest-reward-item"><img src="img/talent-reroll.png" class="quest-reward-inline-img" alt="Talent reroll"> ${r.talentRerolls}</span>`,
    );
  }
  if (r.talentChoices) {
    rewardParts.push(
      `<span class="quest-reward-item"><img src="img/ability-patch.png" class="quest-reward-inline-img" alt="Talent choice"> ${r.talentChoices}</span>`,
    );
  }
  if (r.items) {
    for (const [item, qty] of Object.entries(r.items)) {
      const itemDef = (ALL_ITEMS as Record<string, { name?: string; icon?: string }>)[item]
        ?? { name: item, icon: '' };
      const iconHTML = game.getItemIconHTML?.(itemDef) ?? '';
      rewardParts.push(
        `<span class="quest-reward-item">${iconHTML} ${qty}x ${itemDef.name || item}</span>`,
      );
    }
  }
  if (r.eggs) {
    for (const [rarity, count] of Object.entries(r.eggs)) {
      if (Number(count) <= 0) continue;
      const rarityKey = String(rarity || '').toLowerCase();
      const eggSprite = EGG_SPRITE_BY_RARITY[rarityKey] || EGG_SPRITE_BY_RARITY.common;
      rewardParts.push(
        `<span class="quest-reward-item"><img src="${eggSprite}" class="quest-reward-inline-img quest-reward-egg" alt="Oeuf ${rarity}"> ${count}x ${rarity}</span>`,
      );
    }
  }
  return rewardParts.join('');
}

export function buildAchievementCardHTML(game: GameRuntime, ach: VisibleAchievement): string {
  const localizedAch = game.getLocalizedAchievementData(ach.key, { ...ach });
  const currentVal = (game)
    .getAchievementTrackingValue(ach.trackingKey);
  const target = ach.target;

  let percent = Math.floor((currentVal / target) * 100);
  if (percent > 100) percent = 100;

  const isCompleted = !!(game.achievementsCompleted && game.achievementsCompleted[ach.key]);
  const progressBarColor = isCompleted ? '#4ade80' : '#fbbf24';

  const progressText = isCompleted
    ? game.t('quests.completedLabel')
    : ach.trackingKey === 'totalPlayTime' || ach.trackingKey === 'offlineTimeSimulatedMs'
      ? `${formatTimeString(currentVal)} / ${formatTimeString(target)}`
      : `${formatNumber(currentVal)} / ${formatNumber(target)}`;

  const rewardsHTML = buildRewardsHTML(game, ach);

  const cardHtml = `
                <div class="quest-header">
                    <div class="quest-title" style="color: ${isCompleted ? '#4ade80' : '#fbbf24'};">
                        ${isCompleted ? '' : ''} ${localizedAch.title}
                    </div>
                </div>
                
                <div class="quest-description">${localizedAch.desc}</div>
                
                <div class="quest-progress-container">
    <div class="quest-progress-bar">
        <div class="quest-progress-fill" style="width: ${percent}%; background-color: ${progressBarColor};">
        </div>
    </div>
    
    <div class="quest-progress-text">
        ${progressText}
    </div>
</div>
                
                <div class="quest-rewards">${rewardsHTML}</div>
            `;

  return cardHtml;
}

function toAchievementCard(game: GameRuntime, ach: VisibleAchievement): AchievementCardSnapshot {
  const isCompleted = !!(game.achievementsCompleted && game.achievementsCompleted[ach.key]);
  return {
    achievementKey: ach.key,
    cardClass: `quest-card ${isCompleted ? 'completed' : ''}`,
    cardHtml: buildAchievementCardHTML(game, ach),
  };
}

export function countAchievementsCompleted(game: GameRuntime): number {
  const gm = game;
  if (typeof gm._countAchievementsCompleted !== 'function') return 0;
  return gm._countAchievementsCompleted.call(gm);
}

export function buildAchievementsSnapshot(game: GameRuntime): AchievementsSnapshot {
  const achievementsTotal = Object.keys(ACHIEVEMENTS).length;
  const achievementsCount = countAchievementsCompleted(game);

  const getVisible = (game as GameRuntime & { getVisibleAchievements?: () => VisibleAchievement[] })
    .getVisibleAchievements;
  const visibleList = typeof getVisible === 'function' ? getVisible.call(game) : [];

  const language =
    game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : 'fr';

  if (visibleList.length === 0) {
    return {
      language,
      emptyHtml: `<div class="empty-state">${game.t('quests.achievementsEmptyVisible')}</div>`,
      categories: [],
      achievementsCount,
      achievementsTotal,
    };
  }

  const getCategory = (game as GameRuntime & {
    getAchievementCategoryData: (k: string) => { id: string; label: string };
  }).getAchievementCategoryData;

  const grouped: Record<string, { label: string; items: VisibleAchievement[] }> = {};
  for (const ach of visibleList) {
    const category = getCategory.call(game, ach.trackingKey);
    if (!grouped[category.id]) {
      grouped[category.id] = { label: category.label, items: [] };
    }
    grouped[category.id]!.items.push(ach);
  }

  const categories: AchievementCategorySnapshot[] = [];
  for (const categoryId of CATEGORY_ORDER) {
    const categoryGroup = grouped[categoryId];
    if (!categoryGroup || !categoryGroup.items.length) continue;
    categories.push({
      categoryId,
      title: categoryGroup.label,
      cards: categoryGroup.items.map((ach) => toAchievementCard(game, ach)),
    });
  }

  return {
    language,
    emptyHtml: null,
    categories,
    achievementsCount,
    achievementsTotal,
  };
}

let lastAchievementsSnapshot: AchievementsSnapshot | null = null;

/** @internal Vitest only */
export function resetAchievementsSnapshotDedupForTests(): void {
  lastAchievementsSnapshot = null;
}

/** Build snapshot and publish ACHIEVEMENTS_CHANGED (deduped). */
export function notifyAchievementsChanged(game: GameRuntime): void {
  const achievements = buildAchievementsSnapshot(game);
  if (lastAchievementsSnapshot && !achievementsSnapshotWouldChange(lastAchievementsSnapshot, achievements)) {
    return;
  }
  lastAchievementsSnapshot = achievements;
  publish({ type: Evt.ACHIEVEMENTS_CHANGED, achievements });
}
